  'settings.judgeSection': 'Judgment model (PULY)',
  'settings.judgeHint': 'It is in use now: a step that works in the built-in browser has “PULY (JEV) picks the next step” ticked by default, and when the step’s AI calls on it, PULY is asked once for every move -- turn it off in that step, or set it to only suggest. Only suggesting still asks it; only turning it off stops that. Each time it is asked, this goes to TypeSafe’s cloud: the page’s address and title; the page’s text, up to about 4,000 characters; the words on buttons, links and list choices, up to 60 characters each and a couple of hundred of them; the step’s goal as written in its settings; any note the step’s AI adds (which may carry order details); and the last few moves. So one question can carry far more than 4,000 characters. What is typed into fields is not sent; input boxes, editable areas and parts marked confidential are taken out of the page’s text first, but the words on buttons, links and list choices are sent even from a part marked confidential. The “Where model calls may go” setting does not cover it: it sends even under “Mainland only”. The test asks it one small question (billed once).',
