const dictionaries = { en, 'zh-CN': { ...zh, ...zhTalent, ...zhDynamic } } satisfies Record<Locale, Record<MessageKey, string>>

interface I18nContextValue {
  locale: Locale
  setLocale: (locale: Locale) => void
  t: (key: MessageKey, params?: Record<string, string | number>) => string
  translateMaybe: (namespace: string, value: string | undefined | null) => string
}

const I18nContext = createContext<I18nContextValue | null>(null)

function readInitialLocale(): Locale {
  try {
    const stored = localStorage.getItem(STORAGE_KEY) ?? localStorage.getItem(LEGACY_STORAGE_KEY)
    if (stored === 'en' || stored === 'zh-CN') return stored
  } catch {
    // private mode
  }
  // Ampuly Engine distribution default: Simplified Chinese (switchable to EN).
  return 'zh-CN'
}

function interpolate(template: string, params?: Record<string, string | number>): string {
  if (!params) return template
  return template.replace(/\{(\w+)\}/g, (_, key: string) => (
    Object.prototype.hasOwnProperty.call(params, key) ? String(params[key]) : `{${key}}`
  ))
}

/** The provider's `t`, bound to a locale, for code that runs outside React (lib/ownerCard.ts words a card the same way
 *  a page does; a test words one without a provider). Same dictionary, same fallback to English, same interpolation. */
export function translateFor(locale: Locale): (key: MessageKey, params?: Record<string, string | number>) => string {
  return (key, params) => interpolate(dictionaries[locale][key] ?? dictionaries.en[key] ?? key, params)
}

/** The provider's locale when there is one, else the given one: for a component drawn both under the provider (the
 *  pages) and outside it (the browser pane, which carries its locale as a prop). Never throws. */
export function useLocaleOr(fallback: Locale): Locale {
  return useContext(I18nContext)?.locale ?? fallback
}

/** A refusal the server names by a code (`already_decided`, `gate_not_found` ...), in the reader's words: the sentence
 *  the dictionary has for `<namespace>.<code>`. A code it has no sentence for gets the general `<namespace>.unknown`
 *  sentence with the code in brackets -- the person reads words, and whoever looks into it still has the code. */
export function refusalInWords(locale: Locale, namespace: string, code: unknown, reason?: unknown): string {
  const raw = String(code ?? '').trim()
  const dictionary: Record<string, string> = dictionaries[locale]
  const words = (key: string) => (Object.prototype.hasOwnProperty.call(dictionary, key) ? dictionary[key] : '')
  const known = raw ? words(`${namespace}.${raw}`) : ''
  if (known) return known
  // A reason the server already wrote as a sentence (a budget card's refusal, in the owner's words) is said as it
  // is, not wrapped in the general sentence; a reason that is a code of its own (missing:checkpoint_id) is not shown.
  const said = String(reason ?? '').trim()
  if (said && /\s|[^\x00-\x7F]/.test(said)) return said
  const general = words(`${namespace}.unknown`)
  if (!general) return raw
  if (!raw) return general
  return locale === 'zh-CN' ? `${general}（${raw}）` : `${general} (${raw})`
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(() => readInitialLocale())

  useEffect(() => {
    document.documentElement.lang = locale === 'zh-CN' ? 'zh-CN' : 'en'
  }, [locale])

  const setLocale = useCallback((next: Locale) => {
    setLocaleState(next)
    try {
      localStorage.setItem(STORAGE_KEY, next)
      document.documentElement.lang = next === 'zh-CN' ? 'zh-CN' : 'en'
    } catch {
      // private mode
    }
  }, [])

  const t = useCallback<I18nContextValue['t']>((key, params) => {
    const template = dictionaries[locale][key] ?? dictionaries.en[key] ?? key
    return interpolate(template, params)
  }, [locale])

  const translateMaybe = useCallback<I18nContextValue['translateMaybe']>((namespace, value) => {
    const normalized = String(value ?? '').trim()
    if (!normalized) return ''
    const key = `${namespace}.${normalized}` as MessageKey
    return dictionaries[locale][key] ?? normalized
  }, [locale])

  const value = useMemo<I18nContextValue>(() => ({ locale, setLocale, t, translateMaybe }), [locale, setLocale, t, translateMaybe])

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}

export function useI18n(): I18nContextValue {
  const ctx = useContext(I18nContext)
  if (!ctx) throw new Error('useI18n must be used within I18nProvider')
  return ctx
}
